import{z as s,x as i,o as B,c as p,q as t,j as r,D as e,d as A,s as o,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"费用结构的分类","description":"","frontmatter":{"title":"费用结构的分类","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-fee-taxonomy.md","filePath":"quant/ap-fee-taxonomy.md","lastUpdated":1791413859000}'),d={name:"quant/ap-fee-taxonomy.md"};function u(h,E,m,C,D,f){const n=i("Mermaid");return B(),p("div",null,[E[2]||(E[2]=t('<h1 id="费用结构的分类" tabindex="-1">费用结构的分类 <a class="header-anchor" href="#费用结构的分类" aria-label="Permalink to &quot;费用结构的分类&quot;">​</a></h1><div class="epigraph"><p>把费用说成「一个点」，等于把契约、摩擦与税三种性质不同的漏出压进同一个数；它们可谈判的程度、可度量的途径与对行为的影响各不相同。</p><footer>—— 据 French, The Cost of Active Investing, Journal of Financial Economics, 2008 的成本分类整理</footer></div><p><a href="/quant/ap-return-accounting">上一课</a>把收益钉成口径：同一本账按同一套子区间跑两遍，费前一遍、费后一遍，毛净差整段留给本课。缺口随之而来：<strong>这截差额由哪些科目构成、各记在哪一列</strong>。费用不是一个数而是一张表；分类错了，砍成本会砍错对象，归因会把摩擦当成管理人的功过。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>毛净差几百个基点里，管理费、业绩提成、托管与行政、佣金、价差、冲击、融资、税各占多少？分类错误的代价各不相同：把市场性摩擦（价差与冲击）当成契约费去「谈判压缩」，谈判桌上没有对手方；把业绩提成当线性折扣，会漏掉它作为路径期权的全部行为后果，见<a href="/quant/performance-fee-hwm">业绩费与高水位</a>；把税漏出瀑布，组合层面的优化会整体错位，见<a href="/quant/tax-aware-portfolio">税务感知组合</a>。缺口是一套可执行的分类：每个成本科目都要落进「性质、计提基准、显隐」三个维度。</p><p><span class="marginnote">数字实例：一只 1 亿元的基金，管理费 1% 就是每年 100 万元；若年成交 5 亿元、单边摩擦 10 个基点，交易摩擦又是 50 万元——与契约费同一量级，却几乎不出现在任何账单上。只盯合同费率砍成本，漏掉的正是这后半截。</span></p><h3 id="三个分类维度" tabindex="-1">三个分类维度 <a class="header-anchor" href="#三个分类维度" aria-label="Permalink to &quot;三个分类维度&quot;">​</a></h3><p>按<strong>契约性</strong>分：契约费（管理费、托管费、行政费）写在合同里；市场性成本（价差、冲击、滑点）由市场结构与订单行为决定，见<a href="/quant/slippage-attribution">滑点归因</a>；法定成本（税、印花税，A 股口径见<a href="/quant/cn-fee-structure">费率结构</a>）由辖区规则决定。按<strong>计提基准</strong>分：按 AUM 线性计提、按业绩非线性计提、按事件发生（申购赎回费、转换费）。按<strong>显隐</strong>分：显性账单（佣金、管理费，账上可读）与隐含在成交价里的部分（价差与冲击不出现在任何账单上，只能用执行对比估计）。三维齐全，一个科目才算「入了账」。</p>',8)),(B(),r(l,null,{default:e(()=>[o(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ITEM%7B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E4%B8%AA%E6%88%90%E6%9C%AC%E7%A7%91%E7%9B%AE%2C%20%E5%A6%82%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%22%7D%20--%3E%20D1%7B%22%E6%80%A7%E8%B4%A8%3A%20%E5%A5%91%E7%BA%A6%20%2F%20%E5%B8%82%E5%9C%BA%20%2F%20%E6%B3%95%E5%AE%9A%3F%22%7D%0A%20%20D1%20--%3E%7C%22%E5%B8%82%E5%9C%BA%E6%80%A7%22%7C%20A1%5B%22%E5%AF%B9%E6%89%8B%E6%96%B9%E6%98%AF%E5%B8%82%E5%9C%BA%E7%BB%93%E6%9E%84%2C%20%E5%8F%AA%E8%83%BD%E9%9D%A0%E6%89%A7%E8%A1%8C%E7%AE%A1%E7%90%86%22%5D%0A%20%20ITEM%20--%3E%20D2%7B%22%E8%AE%A1%E6%8F%90%E5%9F%BA%E5%87%86%3A%20AUM%20%2F%20%E4%B8%9A%E7%BB%A9%20%2F%20%E4%BA%8B%E4%BB%B6%3F%22%7D%0A%20%20D2%20--%3E%7C%22%E4%BA%8B%E4%BB%B6%22%7C%20A2%5B%22%E5%8F%AA%E5%9C%A8%E6%88%90%E4%BA%A4%E6%88%96%E7%94%B3%E8%B5%8E%E9%82%A3%E4%B8%80%E5%88%BB%E5%8F%91%E7%94%9F%22%5D%0A%20%20ITEM%20--%3E%20D3%7B%22%E6%98%BE%E6%80%A7%E8%B4%A6%E5%8D%95%E8%BF%98%E6%98%AF%E9%9A%90%E5%90%AB%E5%9C%A8%E4%BB%B7%E6%A0%BC%E9%87%8C%3F%22%7D%0A%20%20D3%20--%3E%7C%22%E9%9A%90%E5%90%AB%22%7C%20A3%5B%22%E8%B4%A6%E4%B8%8A%E8%AF%BB%E4%B8%8D%E5%88%B0%2C%20%E7%94%A8%E6%89%A7%E8%A1%8C%E5%AF%B9%E6%AF%94%E6%9D%A5%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20A1%20--%3E%20DONE%5B%22%E4%B8%89%E7%BB%B4%E9%BD%90%E5%85%A8%2C%20%E7%A7%91%E7%9B%AE%E5%85%A5%E8%B4%A6%22%5D%0A%20%20A2%20--%3E%20DONE%0A%20%20A3%20--%3E%20DONE%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：「显性」是账单上写得出来的数（管理费、佣金）；「隐含」是藏在你成交价里的部分——买得比中间价贵一点、卖得比中间价低一点，没有任何一张发票写明它，只能拿成交价对比同时段中间价来估计。")],-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"French 估计美国主动投资的社会成本每年以千亿美元计，其中交易摩擦与费用各占大头；被动化先吃掉的是契约费那层，摩擦与税原样留在执行与持有层——分类决定了「省钱」能省到哪一层。")],-1)),E[5]||(E[5]=a("h2",{id:"方法",tabindex:"-1"},[A("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[6]||(E[6]=a("p",null,[A("把分类落成一张"),a("strong",null,"费用瀑布"),A("：毛收益、管理费、激励费、交易成本、融资成本、托管运营、税、净收益，逐层相减。每层带四个字段：科目性质（契约/市场/法定）、计提基准（AUM/事件/业绩）、频率（日计提、成交时、年度结晶）、数据来源（账单、成交回报、估值）。验收标准沿用做市课的三问：每一层的数从哪来、谁改过、依据哪条条款；毛净差必须等于各层之和，对不上就是有科目漏记或重复计入，而不是「四舍五入」。")],-1)),(B(),r(l,null,{default:e(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20GROSS%5B%22%E6%AF%9B%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20MGMT%5B%22%E7%AE%A1%E7%90%86%E8%B4%B9%20%E5%A5%91%E7%BA%A6%20AUM%20%E7%BA%BF%E6%80%A7%22%5D%0A%20%20MGMT%20--%3E%20PERF%5B%22%E6%BF%80%E5%8A%B1%E8%B4%B9%20%E5%A5%91%E7%BA%A6%20%E4%B8%9A%E7%BB%A9%20%E9%9D%9E%E7%BA%BF%E6%80%A7%22%5D%0A%20%20PERF%20--%3E%20TRADE%5B%22%E4%BA%A4%E6%98%93%E6%88%90%E6%9C%AC%20%E5%B8%82%E5%9C%BA%20%E4%BA%8B%E4%BB%B6%20%E6%88%90%E4%BA%A4%E6%97%B6%22%5D%0A%20%20TRADE%20--%3E%20FUND%5B%22%E8%9E%8D%E8%B5%84%E6%88%90%E6%9C%AC%20%E5%B8%82%E5%9C%BA%20AUM%20%E6%8C%81%E6%9C%89%E6%9C%9F%22%5D%0A%20%20FUND%20--%3E%20OPS%5B%22%E6%89%98%E7%AE%A1%E8%BF%90%E8%90%A5%20%E5%A5%91%E7%BA%A6%20AUM%20%E7%BA%BF%E6%80%A7%22%5D%0A%20%20OPS%20--%3E%20TAX%5B%22%E7%A8%8E%20%E6%B3%95%E5%AE%9A%20%E4%BA%8B%E4%BB%B6%E4%B8%8E%E6%8C%81%E6%9C%89%E6%9C%9F%22%5D%0A%20%20TAX%20--%3E%20NET%5B%22%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%0A%20%20NET%20--%3E%20CHK%5B%22%E5%A4%8D%E7%AE%97%3A%20%E6%AF%9B%E5%87%80%E5%B7%AE%20%3D%20%E5%90%84%E5%B1%82%E4%B9%8B%E5%92%8C%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分类为什么必须先行：三个维度的成本服从不同的经济机制。契约费是谈判对象，对规模的弹性大，被动化与议价首先压缩它；市场性成本是市场结构的函数，随<a href="/quant/holding-horizon">持有期与换手</a>与订单紧急度变化，只能用算法与执行纪律管理；法定成本是确定性的状态依赖漏出，管理它的手段是持有结构与时点，不是谈判。行为影响也不同：AUM 费不改变单期决策，业绩费改变管理人的风险选择——同样是几百个基点，写在哪一列，意味着完全不同的杠杆。Sharpe 的算术在此给出边界：主动作为一个整体扣费后必然输给被动整体；分类告诉你的是这必然发生<strong>在哪几层</strong>。</p><p><span class="marginnote">直觉类比：契约费像房租，签合同时谈定，到期照付；市场性成本像打车高峰溢价——什么时候出门、走哪条路，决定你多付多少；法定成本像高速收费站，价格钉死，能选的只有路线和时间。三种钱要用三种方式省，这就是分类的意义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>费用如何进入几何收益、复利上吃掉多少终值，主干<a href="/quant/fees-compounding">费用对复合收益</a>已算过，本课不重复公式；业绩费的路径期权结构与水位重置见<a href="/quant/performance-fee-hwm">业绩费与高水位</a>。本课也不谈执行层面的成本优化——那属于交易执行课程，这里只要求成本<strong>可归类、可复算</strong>。瀑布扣完之后数字落到哪条曲线上，是下一课净值构造的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>费用是一张瀑布表，不是一个点；每个科目按性质、计提基准、显隐三维入账。</li><li>契约费、市场性成本、法定成本机制不同：谈判、执行、结构各自对应一层。</li><li>业绩费是非线性的路径条款，不能当线性折扣记。</li><li>毛净差必须等于瀑布各层之和，对不上是漏记，不是舍入。</li><li>出处：French, <em>The Cost of Active Investing</em>, Journal of Financial Economics, 2008；主动算术见 Sharpe, <em>Financial Analysts Journal</em>, 1991。</li></ul>',7))])}const T=s(d,[["render",u]]);export{c as __pageData,T as default};
